<?php
declare(strict_types=1);
namespace Tests\Unit\Modules\Identity\Application;
use LogicException;use Tests\Support\Identity\StatefulAuthorityAffinityTransport;use Tests\Support\Identity\StatefulTenantProbeOrchestrator;use Tests\TestCase;
 final class StatefulTenantProbeOrchestratorTest extends TestCase {
  private function o(?StatefulAuthorityAffinityTransport $transport=null):StatefulTenantProbeOrchestrator{return new StatefulTenantProbeOrchestrator($transport??new StatefulAuthorityAffinityTransport,'run-008');}
 public function test_c04_01_02_a_can_read_create_and_update_own_tenant():void{$o=$this->o();self::assertCount(1,$o->execute('p1','A','A','g1','c1','t1','read','A')['result']);self::assertSame(1,$o->execute('p2','A','A','g2','c1','t2','create','A','x')['result']);self::assertSame(1,$o->execute('p3','A','A','g3','c1','t3','update','A','y')['result']);self::assertSame('y',$o->snapshot('A')['a1']);}
 public function test_c04_03_04_cross_tenant_read_write_denied_without_b_change():void{$o=$this->o();$before=$o->snapshot('B');foreach(['read','create','update','delete']as$i=>$op){try{$o->execute('x'.$i,'A','A','g'.$i,'c1','t'.$i,$op,'B','bad');self::fail('accepted');}catch(LogicException){self::addToAssertionCount(1);}}self::assertSame($before,$o->snapshot('B'));}
 public function test_c04_05_07_08_11_reuse_forgery_revocation_and_replay_fail_closed():void{$o=$this->o();$o->execute('a','A','A','ga','c1','ta','read','A');self::assertCount(1,$o->execute('b','B','B','gb','c1','tb','read','B')['result']);foreach([['bad','A','B'],['b','B','B']]as[$id,$actor,$tenant]){try{$o->execute($id,$actor,$tenant,'g','c','t','read',$tenant);self::fail('accepted');}catch(LogicException){self::addToAssertionCount(1);}}}
  public function test_c04_bind_rejection_resets_owned_transaction_and_allows_new_authority():void{$t=new StatefulAuthorityAffinityTransport;$o=$this->o($t);$t->revoke('revoked');try{$o->execute('revoked','A','A','revoked','c1','t1','read','A');self::fail('accepted');}catch(LogicException $e){self::assertSame('authority-affinity-rejected',$e->getMessage());}self::assertSame(['transaction'=>null,'bound'=>null],$t->state());self::assertSame(['revoke','begin','reset'],$t->events);self::assertCount(1,$o->execute('valid','A','A','valid','c1','t2','read','A')['result']);self::assertSame(['transaction'=>null,'bound'=>null],$t->state());}
  public function test_c04_begin_failure_never_resets_foreign_transaction():void{$t=new StatefulAuthorityAffinityTransport;$t->begin('foreign-c','foreign-t','B','g');$o=$this->o($t);try{$o->execute('blocked','A','A','g2','c1','t1','read','A');self::fail('accepted');}catch(LogicException $e){self::assertSame('nested',$e->getMessage());}self::assertSame('foreign-t',$t->state()['transaction']['transaction']);self::assertSame(['begin'],$t->events);$t->resetOwned('foreign-c','foreign-t');}
  public function test_c04_cleanup_failure_never_returns_success_or_leaks_state():void{$t=new StatefulAuthorityAffinityTransport;$t->failNextReset();$o=$this->o($t);$this->expectException(LogicException::class);$this->expectExceptionMessage('authority-affinity-cleanup-failed');try{$o->execute('cleanup','A','A','g','c','t','read','A');}finally{self::assertSame(['transaction'=>null,'bound'=>null],$t->state());self::assertSame(['begin','bind','write','reset','cleanup-failed'],$t->events);}}
}
